 "content": "from collections import Counter


def transform(grid):
    """Build a filled frame using the color of its sparse internal markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    if len(colors) < 2:
        return out

    # The long bars are the most frequent non-background color; markers are
    # the remaining color. Their shape determines the bounds and carve-outs.
    frame = max(colors, key=lambda v: counts[v])
    mark = next(v for v in colors if v != frame)
    top_cols = [c for c, v in enumerate(grid[0]) if v == frame]
    bottom_cols = [c for c, v in enumerate(grid[-1]) if v == frame]
    if not top_cols or not bottom_cols:
        return out

    # Frame bars are offset: extend each bar's span vertically and fill the
    # enclosed shifted rectangle with frame color.
    left = min(min(top_cols), min(bottom_cols))
    right = max(max(top_cols), max(bottom_cols))
    for r in range(1, h - 1):
        for c in range(left, right + 1):
            if grid[r][c] == background:
                out[r][c] = frame

    # Sparse marks puncture the fill, becoming 4. Keep those cells; all other
    # marker marks are retained as their original mark color.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == mark:
                out[r][c] = 4
    return out


