def _runs(row, color):
    return [i for i, value in enumerate(row) if value == color]


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    if len(colors) < 2:
        return out

    # The repeated edge bars are the most common non-background color;
    # sparse interior points are the other color.
    bar_color = max(colors, key=lambda v: counts[v])
    marker_color = min((v for v in colors if v != bar_color), key=lambda v: counts[v])
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]

    top = _runs(grid[0], bar_color)
    bottom = _runs(grid[-1], bar_color)
    if top and bottom:
        top_lo, top_hi = min(top), max(top)
        bottom_lo, bottom_hi = min(bottom), max(bottom)
        for r, c in markers:
            if top_lo <= c <= top_hi:
                paired = bottom_lo + (c - top_lo)
                direction = -1
            elif bottom_lo <= c <= bottom_hi:
                paired = top_lo + (c - bottom_lo)
                direction = 1
            else:
                continue

            # Extend the marker toward the border bar whose span contains it.
            rr = r + direction
            while 0 <= rr < h:
                if grid[rr][c] == background:
                    out[rr][c] = marker_color
                rr += direction

            # The offset-matched stripe is projected all the way inward from
            # the opposite edge; existing bars and original marks are preserved.
            if 0 <= paired < w:
                for rr in range(h):
                    if grid[rr][paired] == background:
                        out[rr][paired] = marker_color

        for r, c in markers:
            out[r][c] = 4
        return out

    # Transposed case: bars on the left and right borders.
    left = [r for r in range(h) if grid[r][0] == bar_color]
    right = [r for r in range(h) if grid[r][w - 1] == bar_color]
    if left and right:
        left_lo, left_hi = min(left), max(left)
        right_lo, right_hi = min(right), max(right)
        for r, c in markers:
            if left_lo <= r <= left_hi:
                paired = right_lo + (r - left_lo)
                direction = -1
            elif right_lo <= r <= right_hi:
                paired = left_lo + (r - right_lo)
                direction = 1
            else:
                continue
            cc = c + direction
            while 0 <= cc < w:
                if grid[r][cc] == background:
                    out[r][cc] = marker_color
                cc += direction
            if 0 <= paired < h:
                for cc in range(w):
                    if grid[paired][cc] == background:
                        out[paired][cc] = marker_color
        for r, c in markers:
            out[r][c] = 4
    return out


