 "content": "from collections import Counter


def _edge_run(grid, row, color):
    """Return the contiguous color run on an edge row, if present."""
    cols = [c for c, value in enumerate(row) if value == color]
    if not cols:
        return []
    lo, hi = min(cols), max(cols)
    # Edge bars in this task are contiguous runs.
    return list(range(lo, hi + 1))


def transform(grid):
    """Project each sparse marker toward its aligned edge bar and its mate."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    non_background = [value for value in counts if value != background]
    if len(non_background) < 2:
        return out

    # The more frequent non-background color forms the two edge bars; the
    # other color supplies sparse markers and the projected lines.
    bar_color = max(non_background, key=lambda value: counts[value])
    marker_color = min((value for value in non_background if value != bar_color),
                       key=lambda value: counts[value])
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]

    top = _edge_run(grid, grid[0], bar_color)
    bottom = _edge_run(grid, grid[-1], bar_color)
    if top and bottom:
        top_start, bottom_start = top[0], bottom[0]
        top_end, bottom_end = top[-1], bottom[-1]
        for r, c in markers:
            if top_start <= c <= top_end:
                offset = c - top_start
                mate = bottom_start + offset
                step = -1  # the marker's source ray points toward the top bar
            elif bottom_start <= c <= bottom_end:
                offset = c - bottom_start
                mate = top_start + offset
                step = 1   # the marker's source ray points toward the bottom bar
            else:
                continue

            # Extend the source point only toward the bar containing its column.
            rr = r + step
            while 0 < rr < h - 1:
                if grid[rr][c] == background:
                    out[rr][c] = marker_color
                rr += step

            # The corresponding offset in the opposite bar projects across the
            # interior. Original marker cells are changed to 4 afterward.
            if 0 <= mate < w:
                for rr in range(1, h - 1):
                    if grid[rr][mate] == background:
                        out[rr][mate] = marker_color

        for r, c in markers:
            out[r][c] = 4
        return out

    # Rotated version: bars on the left and right edges, markers project along rows.
    left_rows = [r for r in range(h) if grid[r][0] == bar_color]
    right_rows = [r for r in range(h) if grid[r][w - 1] == bar_color]
    if left_rows and right_rows:
        left_start, right_start = min(left_rows), min(right_rows)
        left_end, right_end = max(left_rows), max(right_rows)
        for r, c in markers:
            if left_start <= r <= left_end:
                offset = r - left_start
                mate = right_start + offset
                step = -1
            elif right_start <= r <= right_end:
                offset = r - right_start
                mate = left_start + offset
                step = 1
            else:
                continue
            cc = c + step
            while 0 < cc < w - 1:
                if grid[r][cc] == background:
                    out[r][cc] = marker_color
                cc += step
            if 0 <= mate < h:
                for cc in range(1, w - 1):
                    if grid[mate][cc] == background:
                        out[mate][cc] = marker_color
        for r, c in markers:
            out[r][c] = 4
    return out


