 "content": "from collections import Counter


def transform(grid):
    """Project each marker toward its aligned edge bar and along the paired line."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    if len(colors) < 2:
        return out

    bar = max(colors, key=lambda v: counts[v])
    ink = min((v for v in colors if v != bar), key=lambda v: counts[v])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == ink]

    # Horizontal bars on the top and bottom edges.
    top = [c for c, value in enumerate(grid[0]) if value == bar]
    bottom = [c for c, value in enumerate(grid[-1]) if value == bar]
    if top and bottom:
        top_start, top_end = min(top), max(top)
        bottom_start, bottom_end = min(bottom), max(bottom)
        for r, c in markers:
            if top_start <= c <= top_end:
                paired_col = bottom_start + (c - top_start)
                dr = -1
            elif bottom_start <= c <= bottom_end:
                paired_col = top_start + (c - bottom_start)
                dr = 1
            else:
                continue

            # One-sided ray from the marker toward the edge bar it aligns with.
            rr = r + dr
            while 0 <= rr < h:
                if grid[rr][c] == background:
                    out[rr][c] = ink
                rr += dr

            # Paired offset from the opposite bar extends across the whole board;
            # existing bars and any non-background cells remain unchanged.
            if 0 <= paired_col < w:
                for rr in range(h):
